1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	// Both catalogue figures are read through this one row lookup, so an item's type
48	// is resolved against the catalogue in exactly one place.
49	const catalogueEntryFor = (item: Item) => CATALOGUE[item.type];
50	
51	// Totalling a catalogue column over a list of items is the same operation on the
52	// premium side and the claim side; only the column differs. Naming it once keeps
53	// the two columns visibly separate — which is the point: the building-block
54	// discount rewrites the basePremium column and never touches insuranceValue.
55	const totalOfColumn =
56	  (columnOf: (item: Item) => number) =>
57	  (items: Item[]): number =>
58	    items.reduce((total, item) => total + columnOf(item), 0);
59	
60	const basePremiumOf = (item: Item): number => catalogueEntryFor(item).basePremium;
61	
62	const BLOCK_SIZE = 3;
63	const BLOCK_BASE_PREMIUM = 60;
64	
65	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
66	  alikeItems.length === BLOCK_SIZE;
67	
68	const sumOfBasePremiums = totalOfColumn(basePremiumOf);
69	
70	const CURSE_SURCHARGE_RATE = 0.5;
71	const HIGH_ENCHANTMENT_LEVEL = 5;
72	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
73	
74	const isCursed = (item: Item): boolean => item.cursed === true;
75	
76	// An unenchanted item is enchantment 0, so every threshold reads the level the
77	// same way. The MHPCO sets several enchantment thresholds for different rules;
78	// each names its own level and compares through here.
79	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
80	
81	const carriesEnchantmentSurcharge = (item: Item): boolean =>
82	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
83	
84	// A rate table prices one subject: every row whose risk applies contributes its
85	// rate, and the total is their sum. Both the item surcharges and the policy-wide
86	// modifiers are rate tables — they differ only in what they are applied to.
87	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
88	
89	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
90	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
91	
92	// Every item-specific surcharge is a rate on THAT item's base premium, charged
93	// when its risk applies. Adding a new one means adding a row here — nothing else.
94	const ITEM_SURCHARGES: RateTable<Item> = [
95	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
96	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
97	];
98	
99	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
100	
101	const itemSurchargesOn = (items: Item[]): number =>
102	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
103	
104	// Items of the same type are "alike"; each group is priced together so a
105	// building block can be recognised.
106	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
107	  ...items
108	    .reduce(
109	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
110	      new Map<string, Item[]>(),
111	    )
112	    .values(),
113	];
114	
115	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
116	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
117	
118	const policyBaseOf = (items: Item[]): number =>
119	  alikeItemGroupsIn(items).reduce(
120	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
121	    0,
122	  );
123	
124	// Rounding always favours the MHPCO. Which direction that is follows from which
125	// way the money moves: an amount the office RECEIVES is rounded up, an amount it
126	// PAYS is rounded down. Naming the two directions makes the rule one concept
127	// rather than two opposite-looking halves, and each call site says which kind of
128	// amount it holds — so the reason for the direction is in the code, not a comment.
129	const RECEIVED = Math.ceil;
130	const PAID = Math.floor;
131	
132	const settledInMHPCOsFavour = (
133	  amount: number,
134	  direction: typeof RECEIVED | typeof PAID,
135	): number => direction(amount);
136	
137	const LOYALTY_YEARS = 2;
138	const LOYALTY_DISCOUNT_RATE = -0.2;
139	
140	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
141	
142	// Each item in a quote is treated as a first insurance regardless of customer
143	// history, so this surcharge is unconditional.
144	const appliesUnconditionally = (): boolean => true;
145	
146	const isLongStanding = ({ customer }: QuoteContext): boolean =>
147	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
148	
149	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
150	  precedingQuotes > 0;
151	
152	// A quote is priced from the customer plus its place in the scenario's history.
153	type QuoteContext = { customer: Customer; precedingQuotes: number };
154	
155	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
156	// base that already includes the item surcharges. Surcharges carry a positive
157	// rate, discounts a negative one. Adding a new one means adding a row here.
158	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
159	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
160	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
161	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
162	];
163	
164	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
165	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
166	
167	const quoteFor = (items: Item[], context: QuoteContext): Result => {
168	  const policyBase = policyBaseOf(items);
169	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
170	  return {
171	    premium: settledInMHPCOsFavour(
172	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
173	      RECEIVED,
174	    ),
175	  };
176	};
177	
178	const DEDUCTIBLE_PER_DAMAGE = 100;
179	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
180	
181	const insuranceValueOf = (item: Item): number => catalogueEntryFor(item).insuranceValue;
182	
183	// The insurance sum totals the value column over every insured item — one item,
184	// one row, no grouping. Blocks are a premium concept and cannot reach it.
185	const insuranceSumOf = totalOfColumn(insuranceValueOf);
186	
187	// A policy created by a quote step, tracked by that step's index so later claims
188	// can find it and draw down its cap.
189	type Policy = { items: Item[]; remainingCap: number };
190	
191	const policyFor = (items: Item[]): Policy => ({
192	  items,
193	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
194	});
195	
196	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
197	const HALF_REIMBURSEMENT_RATE = 0.5;
198	const FULL_REIMBURSEMENT_RATE = 1;
199	
200	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
201	// level: this one halves what a claim pays out, that one raises what a policy
202	// costs. They move independently — deliberately not shared.
203	const reimbursesOnlyHalf = (item: Item): boolean =>
204	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
205	
206	// How much of the damage the MHPCO reimburses, before the deductible bites.
207	const reimbursementRateFor = (item: Item): number =>
208	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
209	
210	// A damage names an item type; the policy holds the item it refers to. Which of
211	// several alike items is picked does not matter yet — no test distinguishes them.
212	const damagedItemIn = (policy: Policy, damage: Damage): Item =>
213	  policy.items.find((item) => item.type === damage.itemType)!;
214	
215	const reimbursedAmountFor = (damage: Damage, policy: Policy): number =>
216	  damage.amount * reimbursementRateFor(damagedItemIn(policy, damage));
217	
218	// The deductible bites once per damage, after the reimbursement rate is applied
219	// — never the other way round, which would pay out more.
220	const payoutForDamage = (damage: Damage, policy: Policy): number =>
221	  reimbursedAmountFor(damage, policy) - DEDUCTIBLE_PER_DAMAGE;
222	
223	// One incident can damage several items; each damage is settled on its own
224	// (and so bears its own deductible), and the incident pays out their sum.
225	const payoutForIncident = (incident: Incident, policy: Policy): number =>
226	  incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage, policy), 0);
227	
228	// A payout is drawn from the policy's cap, leaving less for later claims.
229	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
230	  ...policy,
231	  remainingCap: policy.remainingCap - payout,
232	});
233	
234	// The policy pays no more than the cap it has left, however large the damage.
235	const payoutWithinCapOf = (policy: Policy, desiredPayout: number): number =>
236	  Math.min(desiredPayout, policy.remainingCap);
237	
238	// Settling a claim pays out and draws the cap down by the same amount, so the
239	// result the customer sees is the payout plus the cap that payout left behind.
240	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
241	  const payout = settledInMHPCOsFavour(
242	    payoutWithinCapOf(policy, payoutForIncident(incident, policy)),
243	    PAID,
244	  );
245	  const settledPolicy = capDrawnDownBy(policy, payout);
246	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
247	};
248	
249	// What the scenario has accumulated before the current step: the results so far,
250	// the history a quote is priced against, and the policies earlier quotes created.
251	type ScenarioState = {
252	  results: Result[];
253	  precedingQuotes: number;
254	  policies: Record<number, Policy>;
255	};
256	
257	const INITIAL_SCENARIO_STATE: ScenarioState = {
258	  results: [],
259	  precedingQuotes: 0,
260	  policies: {},
261	};
262	
263	// Every step reports exactly one result and leaves one policy at its index —
264	// the two things both step kinds always do. Recording them is named once here
265	// rather than rebuilt in each of them.
266	const withStepRecorded = (
267	  state: ScenarioState,
268	  result: Result,
269	  policyIndex: number,
270	  policy: Policy,
271	): ScenarioState => ({
272	  ...state,
273	  results: [...state.results, result],
274	  policies: { ...state.policies, [policyIndex]: policy },
275	});
276	
277	const afterQuote = (
278	  state: ScenarioState,
279	  items: Item[],
280	  customer: Customer,
281	  stepIndex: number,
282	): ScenarioState => ({
283	  ...withStepRecorded(
284	    state,
285	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
286	    stepIndex,
287	    policyFor(items),
288	  ),
289	  precedingQuotes: state.precedingQuotes + 1,
290	});
291	
292	const afterClaim = (
293	  state: ScenarioState,
294	  policyIndex: number,
295	  incident: Incident,
296	): ScenarioState => {
297	  const [result, settledPolicy] = claimFor(incident, state.policies[policyIndex]);
298	  return withStepRecorded(state, result, policyIndex, settledPolicy);
299	};
300	
301	const afterStep = (
302	  state: ScenarioState,
303	  step: Step,
304	  customer: Customer,
305	  stepIndex: number,
306	): ScenarioState =>
307	  step.op === "quote"
308	    ? afterQuote(state, step.items, customer, stepIndex)
309	    : afterClaim(state, step.policy, step.incident);
310	
311	export const runScenario = (scenario: Scenario): { results: Result[] } => {
312	  const { results } = scenario.steps.reduce(
313	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
314	    INITIAL_SCENARIO_STATE,
315	  );
316	  return { results };
317	};
